package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdReader;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.deser.impl.SettableBeanProperty;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import java.io.*;
import java.io.IOException;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ObjectIdValueProperty_deserializeSetAndReturn_TriageGen0Test {

    @Mock
    private JsonParser mockParser;

    @Mock
    private DeserializationContext mockContext;

    @Mock
    private JsonDeserializer<Object> mockValueDeserializer;

    @Mock
    private ObjectIdReader mockObjectIdReader;

    @Mock
    private ReadableObjectId mockReadableObjectId;

    @Mock
    private SettableBeanProperty mockIdProp;

    @Mock
    private Object mockInstance;

    private ObjectIdValueProperty target;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);

        // Setup the reader mock fields manually as they are accessed directly in the method
        mockObjectIdReader.generator = null; // dummy
        mockObjectIdReader.resolver = null;  // dummy
        mockObjectIdReader.idProperty = null;

        // We need to bypass the fact that ObjectIdReader fields are usually package-private or final
        // In a real Jackson environment, these are set via reflection or internal constructors.
        // Since we are testing the logic, we will use a spy or mock the reader's behavior.

        // Because the method accesses _objectIdReader fields directly, we must ensure 
        // the reader we inject has those fields set.
        // Note: In actual Jackson source, these fields are not final but are part of the reader.

        target = new ObjectIdValueProperty(mockObjectIdReader, null);
        // Use reflection or a helper to set the private/protected _valueDeserializer if necessary, 
        // but here we assume the constructor or withValueDeserializer works.
        target = target.withValueDeserializer(mockValueDeserializer);
    }

    /**
     * Test Case 1: idProperty is NULL.
     * This tests the branch where idProp == null.
     * Expected: returns the instance.
     */
    @Test
    public void testDeserializeSetAndReturn_NoIdProperty() throws IOException {
        Object expectedId = "id-123";
        mockObjectIdReader.idProperty = null;

        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(expectedId);
        when(mockContext.findObjectId(eq(expectedId), any(), any())).thenReturn(mockReadableObjectId);

        Object result = target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        verify(mockValueDeserializer).deserialize(mockParser, mockContext);
        verify(mockContext).findObjectId(eq(expectedId), any(), any());
        verify(mockReadableObjectId).bindItem(mockInstance);
        verify(mockIdProp, never()).setAndReturn(any(), any());
        assertSame("Should return the instance when idProp is null", mockInstance, result);
    }

    /**
     * Test Case 2: idProperty is NOT NULL.
     * This tests the branch where idProp != null.
     * Expected: returns the value returned by idProp.setAndReturn.
     */
    @Test
    public void testDeserializeSetAndReturn_WithIdProperty() throws IOException {
        Object expectedId = "id-456";
        Object returnedValue = "returned-value";
        mockObjectIdReader.idProperty = mockIdProp;

        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(expectedId);
        when(mockContext.findObjectId(eq(expectedId), any(), any())).thenReturn(mockReadableObjectId);
        when(mockIdProp.setAndReturn(mockInstance, expectedId)).thenReturn(returnedValue);

        Object result = target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        verify(mockValueDeserializer).deserialize(mockParser, mockContext);
        verify(mockContext).findObjectId(eq(expectedId), any(), any());
        verify(mockReadableObjectId).bindItem(mockInstance);
        verify(mockIdProp).setAndReturn(mockInstance, expectedId);
        assertEquals("Should return the value from idProp.setAndReturn", returnedValue, result);
    }

    /**
     * Test Case 3: Exception during value deserialization.
     * Ensures exceptions propagate correctly.
     */
    @Test(expected = IOException.class)
    public void testDeserializeSetAndReturn_ThrowsIOException() throws IOException {
        when(mockValueDeserializer.deserialize(any(), any())).thenThrow(new IOException("Parse error"));

        target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);
    }

    /**
     * Test Case 4: Exception during findObjectId.
     */
    @Test(expected = RuntimeException.class)
    public void testDeserializeSetAndReturn_FindObjectIdThrows() throws IOException {
        Object expectedId = "id-error";
        when(mockValueDeserializer.deserialize(any(), any())).thenReturn(expectedId);
        when(mockContext.findObjectId(any(), any(), any())).thenThrow(new RuntimeException("Context error"));

        target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);
    }
}
